-- Restore only the pre-existing Super Admin access to standalone receipts.
-- Finance roles scoped to events do not gain unrelated licence receipts.
begin;
alter policy security_exact_registration_read on public.event_registrations using ((select private.permission_actor_active()) and (((event_id is null and (select public.is_super_admin(auth.email()))) or event_id in (select private.finance_event_ids())) or lower(trim(email))=(select lower(auth.email())) or lower(trim(partner_email))=(select lower(auth.email())) or lower(trim(registered_by))=(select lower(auth.email()))));
alter policy security_exact_registration_update on public.event_registrations using ((select private.permission_actor_active()) and (((event_id is null and (select public.is_super_admin(auth.email()))) or event_id in (select private.finance_event_ids())) or lower(trim(email))=(select lower(auth.email())) or lower(trim(partner_email))=(select lower(auth.email())) or lower(trim(registered_by))=(select lower(auth.email())))) with check ((select private.permission_actor_active()) and (((event_id is null and (select public.is_super_admin(auth.email()))) or event_id in (select private.finance_event_ids())) or lower(trim(email))=(select lower(auth.email())) or lower(trim(partner_email))=(select lower(auth.email())) or lower(trim(registered_by))=(select lower(auth.email()))));
do $$begin if exists(select 1 from pg_policy where polrelid='public.event_registrations'::regclass and polname='Authenticated read own or admin registrations') then alter policy "Authenticated read own or admin registrations" on public.event_registrations using ((select private.permission_actor_active()) and (((event_id is null and (select public.is_super_admin(auth.email()))) or event_id in (select private.finance_event_ids())) or lower(trim(email))=(select lower(auth.email())) or lower(trim(partner_email))=(select lower(auth.email())) or lower(trim(registered_by))=(select lower(auth.email())))); end if; end $$;
do $$begin if exists(select 1 from pg_policy where polrelid='public.event_registrations'::regclass and polname='Authenticated update own or admin registrations') then alter policy "Authenticated update own or admin registrations" on public.event_registrations using ((select private.permission_actor_active()) and (((event_id is null and (select public.is_super_admin(auth.email()))) or event_id in (select private.finance_event_ids())) or lower(trim(email))=(select lower(auth.email())) or lower(trim(partner_email))=(select lower(auth.email())) or lower(trim(registered_by))=(select lower(auth.email())))) with check ((select private.permission_actor_active()) and (((event_id is null and (select public.is_super_admin(auth.email()))) or event_id in (select private.finance_event_ids())) or lower(trim(email))=(select lower(auth.email())) or lower(trim(partner_email))=(select lower(auth.email())) or lower(trim(registered_by))=(select lower(auth.email())))); end if; end $$;
alter policy security_exact_payment_read on public.payments using ((select private.permission_actor_active()) and (((event_id is null and (select public.is_super_admin(auth.email()))) or event_id in (select private.finance_event_ids())) or player_id=(select private.own_payment_player_id()) or lower(trim(metadata->>'email'))=(select lower(auth.email())) or lower(trim(metadata->>'registrant_email'))=(select lower(auth.email()))));
alter policy security_exact_payment_update on public.payments using ((select private.permission_actor_active()) and (((event_id is null and (select public.is_super_admin(auth.email()))) or event_id in (select private.finance_event_ids())) or player_id=(select private.own_payment_player_id()) or lower(trim(metadata->>'email'))=(select lower(auth.email())) or lower(trim(metadata->>'registrant_email'))=(select lower(auth.email())))) with check ((select private.permission_actor_active()) and (((event_id is null and (select public.is_super_admin(auth.email()))) or event_id in (select private.finance_event_ids())) or player_id=(select private.own_payment_player_id()) or lower(trim(metadata->>'email'))=(select lower(auth.email())) or lower(trim(metadata->>'registrant_email'))=(select lower(auth.email()))));
do $$begin if exists(select 1 from pg_policy where polrelid='public.payments'::regclass and polname='Authenticated read own payments') then alter policy "Authenticated read own payments" on public.payments using ((select private.permission_actor_active()) and (((event_id is null and (select public.is_super_admin(auth.email()))) or event_id in (select private.finance_event_ids())) or player_id=(select private.own_payment_player_id()) or lower(trim(metadata->>'email'))=(select lower(auth.email())) or lower(trim(metadata->>'registrant_email'))=(select lower(auth.email())))); end if; end $$;
do $$begin if exists(select 1 from pg_policy where polrelid='public.payments'::regclass and polname='Authenticated update own payments') then alter policy "Authenticated update own payments" on public.payments using ((select private.permission_actor_active()) and (((event_id is null and (select public.is_super_admin(auth.email()))) or event_id in (select private.finance_event_ids())) or player_id=(select private.own_payment_player_id()) or lower(trim(metadata->>'email'))=(select lower(auth.email())) or lower(trim(metadata->>'registrant_email'))=(select lower(auth.email())))) with check ((select private.permission_actor_active()) and (((event_id is null and (select public.is_super_admin(auth.email()))) or event_id in (select private.finance_event_ids())) or player_id=(select private.own_payment_player_id()) or lower(trim(metadata->>'email'))=(select lower(auth.email())) or lower(trim(metadata->>'registrant_email'))=(select lower(auth.email())))); end if; end $$;
alter policy security_scoped_registration_finance_read on public.event_registrations using (((event_id is null and (select public.is_super_admin(auth.email()))) or event_id in (select private.finance_event_ids())));
alter policy security_scoped_registration_finance_update on public.event_registrations using (((event_id is null and (select public.is_super_admin(auth.email()))) or event_id in (select private.finance_event_ids()))) with check (((event_id is null and (select public.is_super_admin(auth.email()))) or event_id in (select private.finance_event_ids())));
alter policy security_scoped_payment_admin on public.payments using (((event_id is null and (select public.is_super_admin(auth.email()))) or event_id in (select private.finance_event_ids()))) with check (((event_id is null and (select public.is_super_admin(auth.email()))) or event_id in (select private.finance_event_ids())));
notify pgrst,'reload schema';
commit;
